CREATE TABLE resource_locks(lock_key varchar(200) PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE tenants(id char(36) PRIMARY KEY, name varchar(200) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE branches(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, name varchar(200) NOT NULL, address varchar(2000) NOT NULL DEFAULT '', UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB;
CREATE TABLE users(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, email varchar(200) NOT NULL UNIQUE, name varchar(200) NOT NULL, password_hash varchar(300) NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('ADMIN','DOCTOR','RECEPTIONIST','NURSE','THERAPIST')), license_number varchar(100), active boolean NOT NULL DEFAULT true, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB;
CREATE TABLE user_branches(user_id char(36) NOT NULL, branch_id char(36) NOT NULL, PRIMARY KEY(user_id,branch_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB;
CREATE TABLE sessions(token_hash varchar(200) PRIMARY KEY, user_id char(36) NOT NULL, csrf_token varchar(200) NOT NULL, expires_at datetime(3) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE patients(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, name varchar(200) NOT NULL, national_id varchar(200) NOT NULL, date_of_birth date NOT NULL, sex varchar(10) NOT NULL CHECK(sex IN ('MALE','FEMALE','OTHER')), phone varchar(50) NOT NULL DEFAULT '', email varchar(200) NOT NULL DEFAULT '', blood_group varchar(10) NOT NULL DEFAULT '', allergies json NOT NULL DEFAULT ('[]'), conditions json NOT NULL DEFAULT ('[]'), notification_consent boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(tenant_id,national_id), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB;
CREATE TABLE rooms(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, name varchar(200) NOT NULL, UNIQUE(tenant_id,branch_id,id), UNIQUE(branch_id,name), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE appointments(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, room_id char(36), starts_at datetime(3) NOT NULL, ends_at datetime(3) NOT NULL, reason varchar(2000) NOT NULL DEFAULT '', status varchar(30) NOT NULL DEFAULT 'BOOKED' CHECK(status IN ('BOOKED','CHECKED_IN','COMPLETED','CANCELLED')), version integer NOT NULL DEFAULT 1, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(ends_at>starts_at), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,branch_id,room_id) REFERENCES rooms(tenant_id,branch_id,id)) ENGINE=InnoDB;
CREATE INDEX appointments_calendar ON appointments(branch_id,starts_at);
CREATE TABLE queue_tickets(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, ticket_number varchar(20) NOT NULL, service_date date NOT NULL, status varchar(30) NOT NULL DEFAULT 'REGISTERED' CHECK(status IN ('REGISTERED','TRIAGE_WAITING','CALLED_TO_ROOM','IN_CONSULTATION','DISPENSARY_WAITING','PAYMENT_WAITING','COMPLETED','SKIPPED')), room_id char(36), practitioner_id char(36), priority varchar(10) NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('NORMAL','URGENT')), version integer NOT NULL DEFAULT 1, called_at datetime(3), completed_at datetime(3), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), active_patient_id char(36) GENERATED ALWAYS AS (CASE WHEN status NOT IN ('COMPLETED','SKIPPED') THEN patient_id ELSE NULL END) STORED, occupied_room_id char(36) GENERATED ALWAYS AS (CASE WHEN status IN ('CALLED_TO_ROOM','IN_CONSULTATION') THEN room_id ELSE NULL END) STORED, UNIQUE(branch_id,active_patient_id), UNIQUE(occupied_room_id), UNIQUE(branch_id,service_date,ticket_number), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,branch_id,room_id) REFERENCES rooms(tenant_id,branch_id,id)) ENGINE=InnoDB;
CREATE INDEX queue_live ON queue_tickets(branch_id,service_date,status,created_at);
CREATE TABLE encounters(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, queue_ticket_id char(36), specialty varchar(20) NOT NULL DEFAULT 'GP' CHECK(specialty IN ('GP','DENTAL','AESTHETIC')), subjective text NOT NULL, objective text NOT NULL, assessment text NOT NULL, plan text NOT NULL, vitals json NOT NULL DEFAULT ('{}'), prescriptions json NOT NULL DEFAULT ('[]'), procedure_notes text NOT NULL, status varchar(30) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SIGNED')), version integer NOT NULL DEFAULT 1, signed_at datetime(3), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,branch_id,queue_ticket_id) REFERENCES queue_tickets(tenant_id,branch_id,id)) ENGINE=InnoDB;
CREATE INDEX encounters_history ON encounters(tenant_id,patient_id,created_at DESC);
CREATE TABLE inventory_items(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, name varchar(200) NOT NULL, sku varchar(200) NOT NULL, ingredient varchar(2000) NOT NULL DEFAULT '', category varchar(30) NOT NULL DEFAULT 'MEDICATION', unit varchar(50) NOT NULL DEFAULT 'unit', price_cents integer NOT NULL CHECK(price_cents>=0), reorder_level integer NOT NULL DEFAULT 10 CHECK(reorder_level>=0), UNIQUE(branch_id,sku), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE inventory_batches(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, item_id char(36) NOT NULL, batch_number varchar(100) NOT NULL, expires_on date NOT NULL, quantity integer NOT NULL CHECK(quantity>=0), received_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(item_id,batch_number), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id,item_id) REFERENCES inventory_items(tenant_id,branch_id,id)) ENGINE=InnoDB;
CREATE INDEX batches_fefo ON inventory_batches(item_id,expires_on,received_at);
CREATE TABLE dispenses(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, encounter_id char(36) NOT NULL, actor_id char(36) NOT NULL, idempotency_key varchar(200) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(encounter_id), UNIQUE(branch_id,idempotency_key), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id,encounter_id) REFERENCES encounters(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE stock_movements(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, batch_id char(36) NOT NULL, dispense_id char(36), quantity_delta integer NOT NULL CHECK(quantity_delta<>0), reason varchar(2000) NOT NULL, actor_id char(36) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id,batch_id) REFERENCES inventory_batches(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id,dispense_id) REFERENCES dispenses(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE treatment_packages(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, name varchar(200) NOT NULL, total_sessions integer NOT NULL CHECK(total_sessions>0), used_sessions integer NOT NULL DEFAULT 0, price_cents integer NOT NULL CHECK(price_cents>=0), expires_on date NOT NULL, version integer NOT NULL DEFAULT 1, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), CHECK(used_sessions>=0 AND used_sessions<=total_sessions)) ENGINE=InnoDB;
CREATE TABLE package_redemptions(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, package_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, encounter_id char(36) NOT NULL, notes text NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(package_id,encounter_id), FOREIGN KEY(tenant_id,branch_id,package_id) REFERENCES treatment_packages(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id,encounter_id) REFERENCES encounters(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE invoices(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, invoice_number varchar(200) NOT NULL UNIQUE, `lines` json NOT NULL, total_cents integer NOT NULL CHECK(total_cents>0), status varchar(30) NOT NULL DEFAULT 'PAID' CHECK(status IN ('PAID','VOID')), idempotency_key varchar(200) NOT NULL, request_hash varchar(2000) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(branch_id,idempotency_key), UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE payments(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, invoice_id char(36) NOT NULL, method varchar(20) NOT NULL CHECK(method IN ('CASH','CARD','QR','DEPOSIT')), amount_cents integer NOT NULL CHECK(amount_cents>0), reference varchar(200) NOT NULL DEFAULT '', created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id,invoice_id) REFERENCES invoices(tenant_id,branch_id,id)) ENGINE=InnoDB;
CREATE TABLE patient_deposits(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, amount_cents integer NOT NULL CHECK(amount_cents<>0), reference varchar(200) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE commission_ledger(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, invoice_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, base_cents integer NOT NULL CHECK(base_cents>0), rate_basis_points integer NOT NULL CHECK(rate_basis_points BETWEEN 0 AND 10000), amount_cents integer NOT NULL CHECK(amount_cents>=0), category varchar(30) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id,invoice_id) REFERENCES invoices(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE TABLE clinical_documents(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, encounter_id char(36) NOT NULL, patient_id char(36) NOT NULL, practitioner_id char(36) NOT NULL, kind varchar(10) NOT NULL CHECK(kind IN ('MC','REFERRAL','LAB')), document_number varchar(200) NOT NULL UNIQUE, payload json NOT NULL, start_date date, end_date date, diagnosis_redacted boolean NOT NULL DEFAULT true, verification_hash varchar(200) NOT NULL UNIQUE, signature_hash varchar(200) NOT NULL, revoked_at datetime(3), revoke_reason text, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(kind<>'MC' OR (start_date IS NOT NULL AND end_date IS NOT NULL AND end_date>=start_date)), FOREIGN KEY(tenant_id,branch_id,encounter_id) REFERENCES encounters(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id), FOREIGN KEY(tenant_id,practitioner_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE INDEX documents_patient ON clinical_documents(tenant_id,patient_id,created_at DESC);
CREATE TABLE notification_outbox(id char(36) PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, patient_id char(36) NOT NULL, channel varchar(20) NOT NULL CHECK(channel IN ('EMAIL','WHATSAPP')), template varchar(50) NOT NULL, recipient varchar(254) NOT NULL, payload json NOT NULL, status varchar(30) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','SENT','FAILED','UNCONFIGURED')), attempts integer NOT NULL DEFAULT 0, available_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), last_error varchar(2000), provider_reference varchar(2000), deduplication_key varchar(200) NOT NULL UNIQUE, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id)) ENGINE=InnoDB;
CREATE INDEX outbox_pending ON notification_outbox(available_at);
CREATE TABLE audit_logs(id bigint AUTO_INCREMENT PRIMARY KEY, tenant_id char(36) NOT NULL, branch_id char(36) NOT NULL, actor_id char(36) NOT NULL, action varchar(30) NOT NULL, entity_type varchar(30) NOT NULL, entity_id char(36), request_id varchar(100) NOT NULL, metadata json NOT NULL DEFAULT ('{}'), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id)) ENGINE=InnoDB;
CREATE INDEX audit_history ON audit_logs(tenant_id,created_at DESC);

